#!/bin/bash
# Installs the nozzle-aware purge Rinkhals app on the printer (run on the Pi as robbie).
set -e
~/pr "mkdir -p /useremain/home/rinkhals/apps/70-nozzle-purge && cd /useremain/home/rinkhals/apps/70-nozzle-purge && echo  | base64 -d | tar xz && chmod +x app.sh && touch .enabled && cp /userdata/app/gk/printer_data/config/printer.custom.cfg /userdata/app/gk/printer_data/config/printer.custom.cfg.bak-$(date +%Y%m%d-%H%M) && sed -i 's/^sweep_speed: \(.*\)$/# sweep_speed: \1  (now set by the nozzle-purge block below)/' /userdata/app/gk/printer_data/config/printer.custom.cfg && python3 nozzle_purge.py && python3 nozzle_purge.py && grep -n -E 'sweep_speed|nozzle' /userdata/app/gk/printer_data/config/printer.custom.cfg"
